<?php include __DIR__.'/../layouts/header.php';?><div class="toolbar"><div><h1 class="page-title">Inscripciones</h1><p class="subtitle">Relación entre estudiantes y cursos.</p></div><a class="btn btn-primary" href="?accion=crear">+ Nueva inscripción</a></div><div class="card"><div class="card-body"><form method="get" class="search-form" style="display:flex;gap:8px;align-items:center;margin-bottom:16px;flex-wrap:wrap"><input class="search" type="search" name="buscar" value="<?=e($busqueda ?? '')?>" placeholder="Buscar inscripción..." style="flex:1;min-width:220px"><button class="btn btn-primary btn-sm" type="submit">Buscar en todos</button><?php if (!empty($busqueda)): ?><a class="btn btn-light btn-sm" href="/controllers/inscripciones.php">Limpiar</a><?php endif; ?></form><div class="table-wrap"><table class="table" id="tabla"><thead><tr><th>Estudiante</th><th>Curso</th><th>Fecha</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($registros as $r):?><tr><td><?=e($r['estudiante'])?></td><td><strong><?=e($r['codigo'])?></strong> · <?=e($r['nombre_curso'])?></td><td><?=e($r['fecha_inscripcion'])?></td><td><span class="badge <?= $r['estado']==='activa'?'badge-success':'badge-warning'?>"><?=e($r['estado'])?></span></td><td><div class="actions"><a class="btn btn-light btn-sm" href="?accion=editar&id=<?=$r['id_inscripcion']?>">Editar</a><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="id" value="<?=$r['id_inscripcion']?>"><button class="btn btn-danger btn-sm" data-confirm="¿Eliminar inscripción?">Eliminar</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php include __DIR__.'/../layouts/paginacion.php'; ?></div></div><?php if($accion!=='listar'):?><div class="modal is-open" data-close-url="/controllers/inscripciones.php" role="dialog" aria-modal="true"><div class="modal-dialog"><div class="modal-header"><h2 style="margin-top:0"><?= $id ? 'Editar':'Nueva'?> inscripción</h2><a class="modal-close" href="/controllers/inscripciones.php" data-modal-close aria-label="Cerrar">×</a></div><div class="modal-body"><?php if ($formError ?? null): ?><div class="alert alert-error" role="alert"><?= e($formError) ?></div><?php endif; ?><form method="post" action="/controllers/inscripciones.php?accion=<?= $id ? 'editar&amp;id='.(int)$id : 'crear' ?>"><input type="hidden" name="id" value="<?= (int)$id ?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="guardar"><div class="grid grid-2"><div class="form-group"><label class="form-label">Estudiante</label><select required name="id_estudiante"><?php if (!$estudiantesDisponibles): ?><option value="">No hay estudiantes registrados</option><?php endif; ?><?php foreach($estudiantesDisponibles as $s):?><option value="<?=$s['id_estudiante']?>" <?=($registro['id_estudiante']??'')==$s['id_estudiante']?'selected':''?>><?=e($s['nombre'].' '.$s['apellido'])?></option><?php endforeach;?></select></div><div class="form-group"><label class="form-label">Curso</label><select required name="id_curso"><?php if (!$cursosDisponibles): ?><option value="">No hay cursos registrados</option><?php endif; ?><?php foreach($cursosDisponibles as $c):?><option value="<?=$c['id_curso']?>" <?=($registro['id_curso']??'')==$c['id_curso']?'selected':''?>><?=e($c['codigo'].' · '.$c['nombre_curso'])?></option><?php endforeach;?></select></div><div class="form-group"><label class="form-label">Fecha</label><?php if($id): ?><input required type="date" name="fecha_inscripcion" value="<?=e($registro['fecha_inscripcion']??date('Y-m-d'))?>" readonly aria-readonly="true"><small class="form-help">La fecha original de la inscripción no se puede modificar.</small><?php else: ?><input required type="date" name="fecha_inscripcion" value="<?=e(date('Y-m-d'))?>" min="<?=e(date('Y-m-d'))?>" max="<?=e(date('Y-m-d'))?>"><small class="form-help">La inscripción debe registrarse con la fecha de hoy.</small><?php endif; ?></div><div class="form-group"><label class="form-label">Estado</label><select name="estado"><option value="activa" <?=($registro['estado']??'activa')==='activa'?'selected':''?>>Activa</option><option value="retirada" <?=($registro['estado']??'')==='retirada'?'selected':''?>>Retirada</option><option value="finalizada" <?=($registro['estado']??'')==='finalizada'?'selected':''?>>Finalizada</option></select></div></div><div class="actions"><button class="btn btn-primary">Guardar</button><a class="btn btn-light" href="/controllers/inscripciones.php">Cancelar</a></div></form></div></div></div><?php endif;?><?php include __DIR__.'/../layouts/footer.php';?>
